 {name:'Snatch',short:'Snatch',load:'9 kg',work:'30 Wdh.',kind:'reps',muscles:'Gesäß, Rücken, Schulter',tip:'Hantel körpernah führen und oben stabil fixieren.',errors:'Zu weite Hantelbahn, instabile Überkopfposition.',prep:'DB High Pull, Hang Snatch',lane:false},
 {name:'Burpee Broad Jump',short:'Burpee Broad Jump',load:'Körpergewicht',work:'30 m',kind:'dist',muscles:'Ganzkörper, Herz-Kreislauf',tip:'Ruhiger Rhythmus, sichere Landung mit anschließendem Bodenkontakt.',errors:'Zu große Sprünge mit unsauberer Landung.',prep:'Burpee Step-back, Broad Jump',lane:true},
 {name:'Goblet Squat',short:'Goblet Squat',load:'12 kg',work:'30 Wdh.',kind:'reps',muscles:'Quadrizeps, Gesäß, Rumpf',tip:'Gewicht dicht am Brustkorb, Knie in Fußrichtung.',errors:'Fersen heben ab, Knie fallen nach innen.',prep:'Tempo Squat, Goblet Hold',lane:false},
 {name:'Front Carry',short:'Front Carry',load:'20 kg',work:'120 m',kind:'dist',muscles:'Rumpf, oberer Rücken, Unterarme',tip:'Scheibe sicher vor dem Körper halten, gleichmäßig atmen.',errors:'Hohlkreuz, Scheibe zu weit vom Körper.',prep:'Bear Hug Carry, Marches',lane:true},
 {name:'Push Press',short:'Push Press',load:'2 × 6 kg',work:'30 Wdh.',kind:'reps',muscles:'Schulter, Trizeps, Beine',tip:'Kurzer Dip, kräftiger Beinantrieb, stabiler Lockout.',errors:'Zu tiefer Dip, Hantel driftet nach vorn.',prep:'DB Strict Press, Push Press',lane:false},
 {name:'Bear Crawl',short:'Bear Crawl',load:'Körpergewicht',work:'60 m',kind:'dist',muscles:'Schultergürtel, Rumpf, Hüfte',tip:'Knie tief, diagonale Bewegung, Becken ruhig.',errors:'Hüfte schaukelt, Knie setzen ab.',prep:'Bear Hover, Shoulder Taps',lane:true},
 {name:'Clean & Press',short:'Clean & Press',load:'10 kg',work:'30 Wdh.',kind:'reps',muscles:'Ganzkörper, Schulter',tip:'Last eng aufnehmen, Rumpf beim Drücken fest.',errors:'Hantel schlägt auf, Überstreckung im Rücken.',prep:'DB Clean, Single-arm Press',lane:false},
 {name:'Overhead Carry',short:'Overhead Carry',load:'10 kg',work:'90 m',kind:'dist',muscles:'Schulterstabilität, Rumpf, Trizeps',tip:'Aktiv nach oben drücken, Rippen unten halten.',errors:'Instabile Schulter, Rippen flare, seitliche Neigung.',prep:'Overhead Hold, Waiter Carry',lane:true},
 {name:'Devil Press',short:'Devil Press',load:'2 × 5 kg',work:'10 Wdh.',kind:'reps',muscles:'Ganzkörper, Schulter, Gesäß',tip:'Hanteln am Boden kontrollieren; flüssiger Übergang in den Lockout.',errors:'Rücken rund beim Aufnehmen, überhasteter Sprung.',prep:'Burpee + DB Deadlift, Devil Press leicht',lane:false}
