const WEEKS = [
 ['Leistungstest & Technik','Einstieg','RPE 6','Baseline ermitteln, alle Stationen sauber lernen.'],
 ['Grundlagen & Griffkraft','Grundlage','RPE 6–7','Aerobe Basis und Carries ohne unnötige Ermüdung.'],
 ['Kraftausdauer','Aufbau','RPE 7','Längere kontrollierte Arbeitsintervalle.'],
 ['Entlastung','Erholung','RPE 5–6','Volumen um etwa ein Drittel reduzieren.'],
 ['Wettkampfgewichte','Aufbau','RPE 7','Wettkampfgewichte technisch sicher bewegen.'],
 ['Laufintervalle','Aufbau','RPE 7–8','Ökonomische 200-m-Abschnitte, kein All-out.'],
 ['Compromised Running','Spezifisch','RPE 7–8','Laufen nach Stationsarbeit bei kontrollierter Pace.'],
 ['Entlastung & Leistungstest','Erholung/Test','RPE 5–7','Erholen und Tests standardisiert wiederholen.'],
 ['Stationsaufteilung','Spezifisch','RPE 7','Beide Zuteilungen testen; Übergaben üben.'],
 ['Wettkampftempo','Spezifisch','RPE 7–8','Zieltempo über wiederholte Teilblöcke festigen.'],
 ['Übergänge & Kraftausdauer','Spezifisch','RPE 7–8','Bewegungsqualität unter Vorermüdung.'],
 ['Entlastung','Erholung','RPE 5–6','Frische herstellen, Technik präzisieren.'],
 ['Wettkampfsimulation','Peak','RPE 8','Kontrollierte Simulation mit realistischer Aufteilung.'],
 ['Generalprobe','Peak','RPE 8','Abläufe, Schuhe, Verpflegung und Pacing erproben.'],
 ['Belastungsreduktion','Taper','RPE 5–7','Volumen senken, kurze zügige Reize halten.'],
 ['Tapering & Wettkampf','Race week','RPE 4–8','Kurz aktivieren, schlafen, gemeinsam starten.']
];
const fmtDate = d => new Intl.DateTimeFormat('de-DE',{day:'2-digit',month:'2-digit'}).format(d);
const weekStart = n => new Date(Date.UTC(2026,10,30+(n-1)*7));
function trainingWeek(n){
 const phase=WEEKS[n-1], scale=[.65,.72,.82,.55,.85,.88,.9,.65,.9,1,.95,.62,1,.92,.58,.35][n-1];
 const reps=Math.max(2,Math.round((3+Math.floor(n/4))*scale));
 const interval= n<=4? '6 × 200 m locker, 75 s Gehpause':n<=8?'8 × 200 m zügig, 75 s Pause':n<=12?'6–8 × 200 m im geplanten Renntempo, 60–75 s Pause':n<=14?'4–6 × 200 m zügig, volle Erholung':'4 × 200 m locker-zügig';
 const stations = n<=2?'Technikzirkel: Deadlift, Goblet Squat, Snatch, Push Press je 3 × 6; Carries 4 × 30 m. Leicht starten.':n<=4?'3 Runden: 8 Deadlifts, 8 Goblet Squats, 6/Seite Snatch, 30 m Farmer Carry; 2 min Pause.':n<=8?'4 Runden: 10 Deadlifts, 10 Lunges (je Seite), 8 Push Press, 40 m Front Carry; Wettkampfgewicht, 2 min Pause.':n<=12?'2 × 3 Stationen in Rennreihenfolge, je halbe Sprint-Arbeit; Partnerwechsel ohne Hantelübergabe.':n<=14?'Wettkampfnahe Teilblöcke mit allen 12 Stationen, Arbeit zwischen euch flexibel aufteilen.':n===15?'2 × 3 Stationen locker, je halbes Volumen; 3 × 200 m Steigerungslauf.':'Kurze Aktivierung 20–25 min; am Renntag offizieller Ablauf.';
 const saturdaySessions = [
 'Baseline ohne All-out: 12 Stationen nacheinander technisch üben. Je 1 × 60 s Farmer 2×16 kg, 8 Deadlifts 24 kg, 10 m Lunges 2×7,5 kg, 6 Snatches/Seite 9 kg, 10 m Burpee Broad Jump, 8 Goblet Squats 12 kg, 20 m Front Carry 20 kg, 8 Push Press 2×6 kg, 10 m Bear Crawl, 8 Clean & Press 10 kg, 15 m Overhead Carry 10 kg, 4 Devil Press 2×5 kg. 90 s Pause; keine Zeitwertung.',
 '4 Runden, 2 min Satzpause: 40 m Farmer Carry 2×16 kg · 10 Deadlifts 24 kg · 20 m Front Carry 20 kg. Danach 3 × 200 m locker, 60 s Gehpause.',
 'Kraftausdauer: 3 Runden, 2 min Pause. 10 m Lunges 2×7,5 kg, 10 Goblet Squats 12 kg, 8 Snatches/Seite 9 kg, 8 Push Press 2×6 kg, 20 m Bear Crawl. Anschließend 4 × (200 m Laufen + 6 Devil Press 2×5 kg), 90 s Pause.',
 'Entlastung: 2 lockere Technikrunden mit je 6 Deadlifts, 6 Goblet Squats, 4 Snatches/Seite, 20 m Farmer Carry, 10 m Bear Crawl. Körpergewicht/leichte Last, 2 min Pause. 20 min sehr locker laufen.',
 'Wettkampfgewichte: 3 Runden, 2 min Pause. 10 Deadlifts 24 kg, 10 Goblet Squats 12 kg, 10 Push Press 2×6 kg, 20 m Front Carry 20 kg, 15 m Overhead Carry 10 kg. Danach 4 × 200 m locker-zügig.',
 'Pace-Intervalle: 5 Runden à 200 m bei geplanter kontrollierter Pace + 8 Walking Lunges/Seite 2×7,5 kg + 8 Push Press 2×6 kg. 90 s Pause nach jeder Runde. Danach 3 × 30 m Farmer Carry.',
 'Compromised Run: 4 Runden: 200 m Laufen + 10 Deadlifts 24 kg + 10 m Burpee Broad Jump + 200 m Laufen. 2 min Pause. Dann 3 × 30 m Carry locker.',
 'Deload/Test: 2 × 200 m Pace-Check mit voller Erholung. Danach Stationstest-Wiederholung in zwei Blöcken à 6 Stationen; standardisierte Last und Arbeit, 2–3 min zwischen Stationen, RPE höchstens 7.',
 'Aufteilung A/B: 2 Blöcke mit je sechs Stationen und je 200 m Lauf davor. Stationen laut Aufteilungsvariante abwechselnd vollständig ausführen; vollständige Sprint-Arbeit (Stationsvolumen) teilen. 3 min Blockpause. Variante nach 10 min Erholung wechseln.',
 'Wettkampftempo: 2 × (3 × 200 m im Zieltempo + jeweils eine Station aus Deadlift, Lunges, Snatch, Goblet Squat, Push Press, Devil Press). Stationsarbeit auf Sprint-Gesamtumfang teilen; 2 min zwischen Abschnitten, 4 min Blockpause.',
 'Übergänge: 3 Runden: 200 m Lauf + 20 m Front Carry 20 kg + 200 m Lauf + 10 Goblet Squats 12 kg + 200 m Lauf + 10 m Burpee Broad Jump. 2 min Satzpause. Ruhige Wechsel, Hantel sicher ablegen.',
 'Entlastung: 25 min locker laufen, danach 2 Technikrunden: 6 Push Press, 6 Goblet Squats, 20 m Farmer Carry und 15 m Overhead Carry mit Wettkampfgewicht; lange Pausen.',
 'Simulation: 12 × 200 m und zwölf Stationen in offizieller Reihenfolge. Wettkampfgewichte und Sprint-Volumen, frei als Pair teilen. RPE im ersten Drittel 6–7, später höchstens 8. Nachbesprechung und keine Zusatzintervalle.',
 'Generalprobe: vollständiger Race Mode mit geplanter Stationsaufteilung, 12 × 200 m und allen Sprint-Stationen. Wettkampfkleidung/Schuhe und Verpflegung erproben. Ziel: kontrolliert, kein All-out; stoppen, wenn Technik deutlich kippt.',
 'Taper: 2 lockere Runden mit je 6 Deadlifts, 6 Goblet Squats, 4 Push Press, 20 m Carry; 3 × 200 m im Zieltempo mit voller Erholung. Gesamtdauer kurz halten.',
 'RACE DAY · 20.03.2027: 12–15 min Warm-up, dann 12 × 200 m gemeinsam und 12 Stationen in Reihenfolge. Freie Pairs-Aufteilung. Bei 200-m-Bahn insgesamt 2,4 km. Startpace kontrolliert, Stationen im vereinbarten Rhythmus.'
 ];
 const saturday = saturdaySessions[n-1];
 const monday = n%4===0?'CrossFit: 35–45 min Technik + moderates Krafttraining, Metcon RPE ≤6.':'CrossFit: reguläre Klasse; Coach über Samstag/Laufen informieren, harte Bein-Metcons bei hoher Wochenlast skalieren.';
 const wednesday = n%4===0?'CrossFit: moderat, Oberkörper/Rumpf priorisieren; keine Max-Versuche.':'CrossFit: Klasse nach Tagesform, RPE max. 7; bei müden Beinen Volumen reduzieren.';
 const sunday = n<=4?'30–40 min lockerer Lauf, Gesprächstempo.':n<=8?'35–45 min locker + '+interval+'.':n<=12?'35 min locker + '+interval+'.':n<=14?'25–35 min locker regenerativ; '+interval+'.':'20–25 min locker, 4 kurze Steigerungen; Renntag nur Race Week.';
 return [
 {day:'Montag',kind:'CrossFit',title:'CrossFit · sinnvoll integrieren',goal:'CrossFit beibehalten, ohne die Deadly-Dozen-Einheit zu sabotieren.',warm:'5–8 min allgemeines Warm-up, Mobilisation nach Klassenplan.',work:monday,rest:'Klassenpausen; keine zusätzlichen Finisher.',rpe:n%4===0?'RPE 5–6':'RPE 6–7',duration:'45–60 min',tech:'Heute zählt die Wochenbelastung: schwere Beine? Skalieren.',scale:'Metcon halbieren, Last um 10–20 % senken.',cool:'5 min lockeres Gehen und Hüft-/Wadenmobilität.'},
 {day:'Mittwoch',kind:'CrossFit',title:'CrossFit · Technik vor Intensität',goal:'Bestehendes Training erhalten und Ermüdung steuern.',warm:'Klassen-Warm-up plus 2 × 10 Glute Bridge und Band Pull-apart.',work:wednesday,rest:'Klassenpausen, bei Bedarf zusätzliche 60–90 s.',rpe:n%4===0?'RPE 5–6':'RPE 6–7',duration:'45–60 min',tech:'Keine zusätzlichen Deadly-Dozen-Maximaltests nach der Klasse.',scale:'WOD in Zone 2–3 halten oder nur Technik absolvieren.',cool:'5 min lockeres Rad/Gehen; Atem beruhigen.'},
 {day:'Samstag',kind:'Team',title:`Team Session · Woche ${n}`,goal:`${phase[3]} Teamkoordination, Kraftausdauer und Stationsroutine.`,warm:'8 min easy jog/Row, dann 2 Runden: 8 Air Squats, 8 Hip Hinge, 6 Push-ups, 20 m leichter Carry; 2 × 60 m Laufsteigerung.',work:saturday,rest:'Zwischen Blöcken 2–3 min; innerhalb der Stationen nach Bedarf kurz absetzen.',rpe:phase[2],duration:n>=13?'60–85 min':'50–70 min',tech:'Gewicht kontrolliert absetzen. Übergabe erst nach Ablegen; beide bleiben bei Distanzstationen zusammen (Regelbuch vor dem Rennen erneut prüfen).',scale:'Arbeit halbieren, Gewicht 10–20 % senken oder Stationen einzeln üben.',cool:'5–8 min Gehen, Waden/Hüfte/Brust mobilisieren, Wasser trinken.'},
 {day:'Sonntag',kind:'Run',title:'Laufen · Aerobe Basis & Pace',goal:'Laufökonomie und gemeinsames Gesprächstempo aufbauen.',warm:'5 min Gehen, 5 min lockeres Traben, dynamische Sprunggelenk- und Hüftmobilität.',work:sunday,rest:'Zwischen Intervallen Gehen oder sehr locker traben.',rpe:n<=4?'RPE 4–5':'RPE 5–7',duration:n<=4?'30–40 min':'40–55 min',tech:'Kurze Schritte, entspannte Schultern; gemeinsame Pace richtet sich nach der langsameren Athletin.',scale:'Nur 20–30 min locker oder Walk-run nach Tagesform.',cool:'5 min gehen, Waden und Hüftbeuger sanft mobilisieren.'}
 ];
}
const base = {version:1,athletes:[{name:'Kerstin',color:'#e9f04b'},{name:'Trainingspartnerin',color:'#73a7ff'}],teamName:'Road to Race',activeAthlete:0,schedule:['Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag','Sonntag'],customWorkouts:[],moves:{},logs:[],tests:[],runs:[],simulations:[],deleted:[],settingsUpdatedAt:0,race:{splits:[],targetSeconds:null,pacing:'',notes:'',checklist:{}},status:'local'};
function load(){try{return {...structuredClone(base),...JSON.parse(localStorage.getItem('ddrz-data')||'{}')}}catch{return structuredClone(base)}}
let db=load(), tab='home', selectedWeek=1, timer=null, stopwatch={startedAt:null,elapsed:0}, raceTimer=null, wake=null;
const save=()=>{localStorage.setItem('ddrz-data',JSON.stringify(db));if(db.status==='online')syncPush();render()};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=new Date(); const tDays=Math.max(0,Math.ceil((new Date(RACE_DATE)-today)/86400000));
const currentWeek=Math.max(1,Math.min(16,Math.floor((today-new Date('2026-11-30T00:00:00'))/604800000)+1));
const weekLabel=n=>{const s=weekStart(n),e=new Date(s);e.setUTCDate(e.getUTCDate()+6);if(n===16)e.setUTCDate(20);return `${fmtDate(s)}–${fmtDate(e)}`};
const h=(tag,attrs={},inner='')=>`<${tag} ${Object.entries(attrs).map(([k,v])=>`${k}="${esc(v)}"`).join(' ')}>${inner}</${tag}>`;
function icon(name){const paths={home:'M3 10 12 3l9 7v10h-6v-6H9v6H3z',calendar:'M4 5h16v16H4z M8 3v4m8-4v4M4 10h16',chart:'M4 19V5m0 14h17M7 15l4-4 3 2 6-7',run:'M13 5a2 2 0 1 0 0-4 2 2 0 0 0 0 4ZM6 13l4-4 4 2 3 4 4 1M10 9l-2 6-4 3m9-7-2 5 4 2',target:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 4a5 5 0 1 0 0 10 5 5 0 0 0 0-10Zm0 4v2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM4 13l-1 2 2 3 2-.4 2 1 .5 2h4l.5-2 2-1 2 .4 2-3-1-2 .1-2 1-1-2-3-2 .4-2-1-.5-2h-4L9 6l-2 1-2-.4-2 3 1 2z'};return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.target}"/></svg>`}
const nav=[['home','Übersicht'],['plan','Plan'],['tests','Tests'],['run','Laufen'],['more','Mehr']];
function render(){
 const app=document.querySelector('#app');
 app.innerHTML=`<div class="shell"><header class="topbar"><a class="brand" href="#home"><span class="brand-mark">DZ</span><span><b>DEADLY DOZEN</b><small>ROAD TO RACE <i>2027</i></small></span></a><button class="sync-pill ${db.status}" data-action="open-settings"><span class="sync-dot"></span>${db.status==='online'?'Synchronisiert':db.status==='pending'?'Wartet auf Netz':'Nur dieses Gerät'}</button></header><main id="view">${view()}</main><nav class="bottom-nav">${nav.map(([id,label])=>`<button class="nav-btn ${tab===id?'active':''}" data-tab="${id}">${icon(id==='more'?'settings':id)}<span>${label}</span></button>`).join('')}</nav></div>`;
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=e=>{e.stopPropagation();action(b.dataset.action,b.dataset)});document.querySelectorAll('[data-week]').forEach(b=>b.onclick=()=>{selectedWeek=+b.dataset.week;render()});document.querySelectorAll('[data-athlete]').forEach(b=>b.onclick=()=>{db.activeAthlete=+b.dataset.athlete;save()});document.querySelectorAll('[data-station]').forEach(b=>b.onclick=e=>{if(e.target.closest('[data-action]'))return;stationModal(+b.dataset.station)});document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>toggle(b.dataset.toggle));
 const form=document.querySelector('#quick-log');if(form)form.onsubmit=e=>{e.preventDefault();addLog(new FormData(form));};const runform=document.querySelector('#run-form');if(runform)runform.onsubmit=e=>{e.preventDefault();addRun(new FormData(runform));};
}
function view(){if(tab==='plan')return planView();if(tab==='tests')return testsView();if(tab==='run')return runView();if(tab==='more')return moreView();return homeView()}
function homeView(){const logs=db.logs.slice().sort((a,b)=>b.date.localeCompare(a.date));const weekLogs=logs.filter(x=>x.date>=weekLabel(currentWeek).slice(0,5));const nDone=db.logs.length;const next=trainingWeek(currentWeek).find(s=>s.day==='Samstag');const testsCount=db.tests.length;return `<section class="hero"><div class="hero-copy"><span class="eyebrow"><span class="live-dot"></span> TEAM TRAINING HUB</span><h1>Train together.<br><em>Race together.</em></h1><p>16 Wochen. 12 Stationen. Ein gemeinsames Ziel.</p></div><div class="race-count"><strong>${tDays}</strong><span>TAGE BIS ZUM RACE</span><div class="race-date">20 <small>MÄR</small> 2027</div></div><div class="hero-glow"></div></section>
 <section class="phase-row"><div class="phase-card"><span>AKTUELLE WOCHE</span><b>Woche ${currentWeek}<small> / 16</small></b><div class="progress-track"><i style="width:${Math.round(currentWeek/16*100)}%"></i></div><small>${weekLabel(currentWeek)}</small></div><div class="phase-card"><span>TRAININGSPHASE</span><b>${WEEKS[currentWeek-1][1]}</b><small>${WEEKS[currentWeek-1][0]}</small></div><div class="phase-card next-session"><span>NÄCHSTE TEAM-EINHEIT</span><b>Samstag</b><small>${next?.title||'Team Session'}</small><button class="text-link" data-tab="plan">Einheit ansehen ↗</button></div></section>
 <section class="section-head"><div><span class="eyebrow">DAS TEAM</span><h2>Unser Fortschritt</h2></div><button class="outline-btn" data-action="athlete-edit">Namen bearbeiten</button></section><section class="athlete-grid">${db.athletes.map((a,i)=>{const total=db.logs.filter(l=>l.athlete===i).length;const best=db.tests.filter(t=>t.athlete===i).reduce((m,t)=>Math.min(m,t.seconds||Infinity),Infinity);return `<article class="athlete-card" style="--athlete:${a.color}"><div class="athlete-top"><span class="avatar">${esc((a.name||'A').slice(0,1).toUpperCase())}</span><div><b>${esc(a.name)}</b><small>${i===0?'ATHLETIN 01':'ATHLETIN 02'}</small></div><button class="dots" data-athlete="${i}">•••</button></div><div class="athlete-stats"><div><strong>${total}</strong><small>Workouts</small></div><div><strong>${Number.isFinite(best)?formatTime(best):'—'}</strong><small>Stations-Bestzeit</small></div><div><strong>${Math.min(100,Math.round(total/48*100))}%</strong><small>Konstanz</small></div></div><div class="mini-bars">${Array.from({length:8},(_,k)=>{const from=new Date();from.setDate(from.getDate()-(8-k)*7);const to=new Date(from);to.setDate(to.getDate()+7);const count=db.logs.filter(l=>l.athlete===i&&new Date(l.date)>=from&&new Date(l.date)<to).length;return `<i title="${count} Workouts" style="height:${Math.max(10,Math.min(100,count*34))}%"></i>`}).join('')}</div></article>`}).join('')}</section>
 <section class="stats-grid"><article class="stat-panel"><span class="eyebrow">TEAM VOLUME</span><strong>${db.logs.length}</strong><small>erfasste Trainingseinheiten</small><div class="stat-foot">${db.logs.filter(l=>l.shared).length} gemeinsam absolviert</div></article><article class="stat-panel"><span class="eyebrow">PERFORMANCE TEST</span><strong>${testsCount}<small> / 24</small></strong><small>Testeinträge aus 12 Stationen</small><button class="text-link" data-tab="tests">Leistungen dokumentieren ↗</button></article><article class="stat-panel"><span class="eyebrow">LAUFUMFANG</span><strong>${db.runs.reduce((s,r)=>s+Number(r.distance||0),0).toFixed(1)}<small> km</small></strong><small>${db.runs.length} dokumentierte Läufe</small><button class="text-link" data-tab="run">Läufe ansehen ↗</button></article></section>
 <section class="section-head"><div><span class="eyebrow">LETZTE EINTRÄGE</span><h2>Trainingshistorie</h2></div><button class="outline-btn" data-action="add-log">+ Einheit erfassen</button></section>${logs.length?`<section class="log-list">${logs.slice(0,4).map(l=>`<article class="log-row"><span class="log-icon">${icon(l.type==='Run'?'run':'target')}</span><div><b>${esc(l.title)}</b><small>${new Date(l.date+'T12:00').toLocaleDateString('de-DE')} · ${esc(db.athletes[l.athlete]?.name)} ${l.shared?'· Team':''}</small></div><strong>${esc(l.duration||'')}</strong><button class="tiny-action" data-action="edit-log" data-id="${l.id}">Bearbeiten</button><button class="tiny-action danger" data-action="delete-log" data-id="${l.id}">×</button></article>`).join('')}</section>`:`<div class="empty-state">Noch keine Trainingsdaten. Öffne den Plan und hake deine erste Einheit ab.</div>`}
 <section class="notice-bar"><span class="notice-icon">✦</span><div><b>Wettkampfprognose</b><p>${db.tests.length>=12?'Datenbasis vorhanden – Prognose in Tests ansehen.':'Noch keine Prognose: erst vergleichbare Stationstests erfassen. Keine Scheingenauigkeit.'}</p></div><button class="text-link" data-tab="tests">Zu Performance Tests ↗</button></section>`}
function planView(){return `<section class="page-intro"><span class="eyebrow">16-WOCHEN-PERIODISIERUNG</span><h1>Trainingsplan<span class="accent">.</span></h1><p>Das CrossFit bleibt Teil eurer Woche. Passe Last und Metcon an, damit die spezifischen Einheiten Qualität behalten.</p></section><div class="week-strip">${WEEKS.map((w,i)=>`<button data-week="${i+1}" class="week-chip ${selectedWeek===i+1?'selected':''} ${currentWeek===i+1?'current':''}"><small>W${String(i+1).padStart(2,'0')}</small><b>${fmtDate(weekStart(i+1))}</b></button>`).join('')}</div><section class="week-heading"><div><span class="eyebrow">WOCHE ${String(selectedWeek).padStart(2,'0')} · ${weekLabel(selectedWeek)}</span><h2>${WEEKS[selectedWeek-1][0]}</h2><p>${WEEKS[selectedWeek-1][3]}</p></div><button class="outline-btn" data-action="custom-workout">＋ Eigene Einheit</button></section><div class="session-list">${trainingWeek(selectedWeek).map((s,i)=>sessionCard(s,selectedWeek,i)).join('')}${db.customWorkouts.filter(w=>w.week===selectedWeek).map(w=>sessionCard({...w,day:w.day||'Eigene Einheit',kind:'Custom'},selectedWeek,99)).join('')}</div><section class="plan-guidance"><b>Belastungssteuerung</b><p>Montag/Mittwoch CrossFit zählen zur Wochenlast. Fällt ein sehr intensiver Bein-Metcon an, kürzt die Zusatzarbeit oder ersetzt sie durch Technik. Samstag bleibt spezifisch, Sonntag überwiegend locker. Schmerzen oder anhaltende Erschöpfung sind ein Signal zum Skalieren.</p></section>`}
function sessionCard(s,w,i){const date=new Date(weekStart(w));date.setUTCDate(date.getUTCDate()+({Montag:0,Mittwoch:2,Samstag:5,Sonntag:6}[s.day]??0));const isCustom=s.kind==='Custom',isDone=isCustom?db.logs.some(l=>l.customId===s.id&&l.athlete===db.activeAthlete):db.logs.some(l=>l.week===w&&l.session===i&&l.athlete===db.activeAthlete);const moveKey=`${w}:${i}`,dateShown=db.moves?.[moveKey]?new Date(db.moves[moveKey]+'T12:00'):date;return `<article class="session-card ${isDone?'done':''}"><div class="session-date"><b>${s.day.slice(0,3)}</b><small>${fmtDate(dateShown)}</small></div><div class="session-main"><div class="session-meta"><span class="tag ${s.kind.toLowerCase()}">${s.kind}</span><span>${s.duration} · ${s.rpe}</span></div><h3>${esc(s.title)}</h3><p>${esc(s.goal)}</p><details><summary>Einheit im Detail</summary><div class="detail-grid"><div><b>Warm-up</b><p>${esc(s.warm)}</p></div><div><b>Übungen / Hauptteil</b><p>${esc(s.work)}</p></div><div><b>Pause & Intensität</b><p>${esc(s.rest)} Ziel: ${esc(s.rpe)}</p></div><div><b>Technik & Skalierung</b><p>${esc(s.tech)} ${esc(s.scale)}</p></div><div><b>Cool-down</b><p>${esc(s.cool)}</p></div></div></details></div><div class="session-actions"><button class="check-btn ${isDone?'checked':''}" ${isCustom?`data-action="toggle-custom" data-id="${s.id}"`:`data-toggle="${w}:${i}"`}>${isDone?'✓':'＋'}<span>${isDone?'Erledigt':'Loggen'}</span></button><button class="shift-btn" data-action="move-session" data-key="${moveKey}" data-date="${dateShown.toISOString().slice(0,10)}" aria-label="Einheit verschieben">↗</button></div></article>`}
function testsView(){const station=STATIONS.map((s,i)=>{const items=db.tests.filter(t=>t.station===i).sort((a,b)=>a.date.localeCompare(b.date));return `<article class="station-test" data-station="${i}"><div class="station-no">${String(i+1).padStart(2,'0')}</div><div class="station-info"><h3>${s.name}</h3><span>${s.load} <i>·</i> ${s.work}</span></div><div class="station-best">${stationSummary(i,db.activeAthlete)}</div><button class="icon-btn" aria-label="Stationstest erfassen">＋</button>${items.length?`<div class="station-history">${items.slice(-3).reverse().map(t=>`<span>${esc(db.athletes[t.athlete]?.name)} · ${formatTime(t.seconds)} · ${new Date(t.date+'T12:00').toLocaleDateString('de-DE')} <button data-action="edit-test" data-id="${t.id}">Bearbeiten</button><button data-action="delete-test" data-id="${t.id}">×</button></span>`).join('')}</div>`:''}</article>`}).join('');const a=allocation();return `<section class="page-intro"><span class="eyebrow">TEAM PERFORMANCE TEST</span><h1>Leistung messen<span class="accent">.</span></h1><p>Erfasse standardisierte Einzelstationen und vergleiche nur Leistungen mit gleichem Gewicht, Umfang und Testbedingungen.</p></section><div class="athlete-switch">${db.athletes.map((a,i)=>`<button data-athlete="${i}" class="${i===db.activeAthlete?'active':''}" style="--athlete:${a.color}">${esc(a.name)}</button>`).join('')}</div><div class="test-toolbar"><div><b>${db.tests.length} Testeinträge</b><small>Bestzeit · Durchschnitt · Verbesserung</small></div><button class="outline-btn" data-action="stopwatch">⏱ Stoppuhr</button></div><div class="station-list">${station}</div><section class="allocation"><div class="section-head compact"><div><span class="eyebrow">RECHNERISCHER VERGLEICH</span><h2>Stationsaufteilung</h2></div><select id="allocation-select"><option value="A">Variante A</option><option value="B">Variante B</option><option value="C">Beste Station je Athletin · flexibel</option></select></div><p>Grundlage: schnellste gültige, vergleichbare Zeiten pro Station. Pausen, RPE, Technik und Laufbelastung sind qualitative Hinweise und fließen mangels valider Umrechnung nicht als Minutenbonus in die Zeit ein.</p><div class="allocation-grid">${['A','B','C'].map(v=>{const val=allocation(v);return `<div class="allocation-card ${v===a.recommended?'recommended':''}"><span>${v==='C'?'FLEXIBEL · BESTE TESTZEIT':`VARIANTE ${v}`} ${v===a.recommended?'· SCHNELLSTE A/B':''}</span><strong>${val.total?formatTime(val.total):'—'}</strong><small>${val.missing?`${val.missing} Stationen ohne vergleichbare Tests`:v==='C'?'Hypothetisch: ganze Station jeweils an die schnellere Athletin':'Summe der Stationen mit kompletter Zuteilung'}</small><div class="split-pills"><i>${db.athletes[0].name}: ${formatTime(val.p1)}</i><i>${db.athletes[1].name}: ${formatTime(val.p2)}</i></div></div>`}).join('')}</div><div class="qualitative"><b>Qualitative Empfehlung</b><p>${a.recommended?`Variante ${a.recommended} ist nach den jeweils schnellsten standardisierten Einzelzeiten rechnerisch schneller. Vergleicht zusätzlich RPE, Pausen und technische Sicherheit pro zugewiesener Station.`:'Noch keine ausreichenden vergleichbaren Daten für eine A/B-Empfehlung. Testet die Stationen standardisiert und legt die finale Aufteilung gemeinsam fest.'} Bei Stationen mit RPE ≥ 8 oder mindestens zwei Pausen plant kürzere Arbeitsblöcke und sichert die Technik. Überlappende Griff- und Schulterermüdung kann die folgenden 200-m-Läufe beeinflussen; die Zeitformel rechnet das nicht in Minuten um. Es ist keine offizielle Empfehlung des Veranstalters.</p></div><button class="outline-btn" data-action="edit-splits">Aufteilung manuell festlegen</button></section><section class="projection"><span class="eyebrow">PROGNOSE</span><h2>${db.tests.length>=12?'Stationen erfassbar':'Noch keine Zielzeit'}</h2><p>Eine belastbare Gesamtzeit braucht vergleichbare Tests aller Stationen und realistische 200-m-Laufzeiten. Die App zeigt keine scheinpräzise Zeit.</p></section>`}
function bestTime(i,ath){const x=db.tests.filter(t=>t.station===i&&t.athlete===ath&&t.valid!==false&&comparable(t));return x.length?formatTime(Math.min(...x.map(y=>y.seconds))):'—'}
function stationSummary(i,ath){const xs=db.tests.filter(t=>t.station===i&&t.athlete===ath&&t.valid!==false&&comparable(t)).sort((a,b)=>a.date.localeCompare(b.date));if(!xs.length)return '<b>—</b><small>noch kein Test</small>';const best=Math.min(...xs.map(x=>x.seconds)),avg=Math.round(xs.reduce((n,x)=>n+x.seconds,0)/xs.length),im=improvementPercent(xs[0].seconds,best);return `<b>${formatTime(best)}</b><small>Ø ${formatTime(avg)}${im!=null&&im>0?` · −${im}%`:''}</small>`}
function comparable(t){let s=STATIONS[t.station];return (!t.load||t.load===s.load)&&(!t.work||t.work===s.work)}
function allocation(variant='A'){const raw=calculateAssignments(STATIONS.map((s,index)=>({index,load:s.load,work:s.work})),db.tests,variant);return {p1:raw.athlete1,p2:raw.athlete2,total:raw.total,missing:raw.missing,recommended:raw.missing===0?(allocationRaw('A')<=allocationRaw('B')?'A':'B'):null}}
function allocationRaw(variant){return calculateAssignments(STATIONS.map((s,index)=>({index,load:s.load,work:s.work})),db.tests,variant).total}
function runView(){const runs=db.runs.slice().sort((a,b)=>a.date.localeCompare(b.date));const pace=runs.length?runs.reduce((x,r)=>x+Number(r.seconds||0),0)/runs.reduce((x,r)=>x+Number(r.distance||0),0):0;return `<section class="page-intro"><span class="eyebrow">RUN TRAINING</span><h1>Run your pace<span class="accent">.</span></h1><p>Die Läufe gemeinsam absolvieren. Pace und Belastung individuell notieren.</p></section><div class="pace-calc"><div><span class="eyebrow">PACE-RECHNER</span><h2>200 m auf den Punkt</h2><div class="form-row"><label>Tempo (min/km)<input id="pace-input" type="number" step="0.05" value="${pace?(pace/60).toFixed(2):'6.00'}"></label><label>Gesamtläufe<input value="12 × 200 m" disabled></label></div><div class="pace-result"><div><span>ZEIT / 200 M</span><b id="pace-200">—</b></div><div><span>ZEIT FÜR 2,4 KM</span><b id="pace-total">—</b></div><div><span>+ 30 SEK / KM</span><b id="pace-delta">—</b></div></div><small>Die Laufzeit ist eine Rechenhilfe ohne Stationszeit, Übergänge oder Ermüdungsfaktor.</small></div><div class="pace-side"><span>GEMEINSAME PACE</span><b>${pace?formatPace(pace):'—'}</b><small>${pace?'Aus deinen Laufdaten gemitteltes Tempo':'Noch keine Laufdaten vorhanden'}</small></div></div><section class="section-head"><div><span class="eyebrow">TRAININGSLOG</span><h2>Lauf erfassen</h2></div><button class="outline-btn" data-action="toggle-run-form">＋ Neuer Lauf</button></section><form class="entry-form hidden" id="run-form"><label>Datum<input name="date" type="date" value="${new Date().toISOString().slice(0,10)}" required></label><label>Distanz km<input name="distance" type="number" step="0.01" min="0.1" required></label><label>Zeit mm:ss<input name="time" placeholder="32:15" required></label><label>Herzfrequenz (optional)<input name="hr" type="number" min="30" max="230"></label><label>RPE 1–10<input name="rpe" type="number" min="1" max="10"></label><label class="span-2">Notiz<input name="notes" placeholder="z. B. locker, gemeinsam, vorermüdet"></label><label class="check-label"><input name="shared" type="checkbox"> Gemeinsam gelaufen</label><button class="primary-btn">Lauf speichern</button></form><section class="chart-card"><div class="chart-header"><div><span class="eyebrow">LAUFENTWICKLUNG</span><h3>Tempo je Kilometer</h3></div><div class="legend">${db.athletes.map(a=>`<span style="--athlete:${a.color}">${esc(a.name)}</span>`).join('')}</div></div>${runs.length?`<div class="run-chart">${runs.slice(-12).map(r=>`<div class="run-point"><i style="height:${Math.min(100,Math.max(12,95-(Number(r.seconds)/Number(r.distance)-240)/3))}%"></i><small>${new Date(r.date+'T12:00').toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit'})}</small><b>${formatPace(r.seconds/Number(r.distance))}</b></div>`).join('')}</div>`:'<div class="empty-state">Nach den ersten Läufen erscheint hier eure Pace-Entwicklung.</div>'}</section><section class="log-list">${runs.slice().reverse().slice(0,8).map(r=>`<article class="log-row"><span class="log-icon">${icon('run')}</span><div><b>${r.distance} km · ${formatTime(r.seconds)}</b><small>${new Date(r.date+'T12:00').toLocaleDateString('de-DE')} · ${formatPace(r.seconds/r.distance)}${r.shared?' · Team':''}</small></div><small>RPE ${r.rpe||'—'}</small></article>`).join('')}</section>`}
function moreView(){return `<section class="page-intro"><span class="eyebrow">TEAM HUB</span><h1>Mehr Bereiche<span class="accent">.</span></h1><p>Werkzeuge, gemeinsame Strategie und Team-Einstellungen.</p></section><div class="more-grid"><button data-action="library"><span>12</span><b>Übungsbibliothek</b><small>Technik, Loads, Fehlerbilder</small></button><button data-action="race"><span>▶</span><b>Race Mode</b><small>Große Tasten, Splits und Gesamtzeit</small></button><button data-action="strategy"><span>↗</span><b>Wettkampfstrategie</b><small>Aufteilung, Zielsetzung, Checkliste</small></button><button data-action="open-settings"><span>⚙</span><b>Team & Einstellungen</b><small>Sync, Namen, Daten exportieren</small></button></div>${db.simulations.length?`<section class="section-head"><div><span class="eyebrow">RACE HISTORY</span><h2>Letzte Simulationen</h2></div></section><section class="log-list">${db.simulations.slice().reverse().slice(0,5).map(x=>`<article class="log-row"><span class="log-icon">${icon('target')}</span><div><b>${formatTime(x.seconds)} · ${new Date(x.date).toLocaleDateString('de-DE')}${db.simulations.length>1&&db.simulations.at(-1)?.id===x.id?` · ${x.seconds<db.simulations.at(-2).seconds?'−':'+'}${formatTime(Math.abs(x.seconds-db.simulations.at(-2).seconds))} zur letzten`:''}</b><small>Lauf ${formatTime(x.runSeconds||0)} · Stationen ${formatTime(x.stationSeconds||0)} · schnellste ${formatTime(x.fastest||0)} · langsamste ${formatTime(x.slowest||0)}</small><details><summary>Alle Zwischenzeiten</summary><small>${(x.splits||[]).map(p=>`${p.type==='run'?'Lauf '+(p.station+1):'Station '+(p.station+1)} ${formatTime(p.seconds)}`).join(' · ')}</small></details></div></article>`).join('')}</section>`:``}<section class="rule-card"><span class="eyebrow">REGELWERK · OFFIZIELLE QUELLEN</span><h2>Regeln vor dem Start prüfen</h2><p>Das Event bestätigt: Deadly Sprint am 20.03.2027 in Sindelfingen, 12 × 200 m (2,4 km), 50 % der Stationenarbeit und unveränderte Frauen-Gewichte. Pairs wechseln an Stationen und laufen gemeinsam. Das offizielle Regelbuch ist die maßgebliche Quelle für Standards und Sanktionen.</p><a href="https://deadlydozen.de/sprint" target="_blank" rel="noopener">Deadly Sprint · Eventseite ↗</a><a href="https://www.deadlydozen.com/rulebook" target="_blank" rel="noopener">Aktuelles offizielles Regelbuch ↗</a><p class="unconfirmed">Nicht bestätigte Einzelheiten zu No-reps, Strafzeiten und Ausrüstung werden hier nicht behauptet. Die Stationsdaten lassen sich in den Einstellungen anpassen.</p></section>`}
function action(type,data={}){if(type==='open-settings')settingsModal();if(type==='athlete-edit')athletesModal();if(type==='stopwatch')stopwatchModal();if(type==='delete-test'){db.deleted.push({id:crypto.randomUUID(),target:'test:'+data.id,updatedAt:Date.now()});db.tests=db.tests.filter(t=>t.id!==data.id);save()}if(type==='edit-test')editTest(data.id);if(type==='add-log')logModal();if(type==='edit-log')editLog(data.id);if(type==='delete-log'){db.deleted.push({id:crypto.randomUUID(),target:'log:'+data.id,updatedAt:Date.now()});db.logs=db.logs.filter(x=>x.id!==data.id);save()}if(type==='toggle-run-form'){document.querySelector('#run-form')?.classList.toggle('hidden')}if(type==='custom-workout')customModal();if(type==='move-session')moveSession(data.key,data.date);if(type==='toggle-custom')toggleCustom(data.id);if(type==='edit-splits')splitsModal();if(type==='race')raceMode();if(type==='library')libraryView();if(type==='strategy')strategyModal();if(type==='export')exportData();if(type==='import')importData();if(type==='logout')signOut();if(type==='auth')authModal();if(type==='make-team')makeTeam();if(type==='join-team')joinTeam();if(type==='sync-now')syncPull(true)}
function modal(title,body,submitLabel='Speichern'){const d=document.querySelector('#modal');d.innerHTML=`<form method="dialog" class="modal-card"><button class="modal-close" value="cancel" aria-label="Schließen">×</button><span class="eyebrow">ROAD TO RACE 2027</span><h2>${title}</h2><div class="modal-body">${body}</div><div class="modal-actions"><button class="outline-btn" value="cancel">Abbrechen</button><button class="primary-btn" value="default">${submitLabel}</button></div></form>`;d.showModal();return d.querySelector('form')}
function logModal(existing=null){const x=existing||{};const f=modal(existing?'Trainingseinheit bearbeiten':'Training dokumentieren',`<div class="form-grid"><label>Datum<input name="date" type="date" value="${x.date||new Date().toISOString().slice(0,10)}" required></label><label>Athletin<select name="athlete">${db.athletes.map((a,i)=>`<option value="${i}" ${(x.athlete??db.activeAthlete)===i?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><label class="span-2">Trainingseinheit<input name="title" value="${esc(x.title||'')}" required placeholder="z. B. Kraftausdauer, CrossFit"></label><label>Dauer<input name="duration" value="${esc(x.duration||'')}" placeholder="55 min"></label><label>RPE 1–10<input name="rpe" type="number" min="1" max="10" value="${x.rpe||''}"></label><label>Gewicht / Last<input name="weight" value="${esc(x.weight||'')}"></label><label>Wiederholungen<input name="reps" value="${esc(x.reps||'')}"></label><label>Distanz<input name="distance" value="${esc(x.distance||'')}" placeholder="z. B. 4 km"></label><label class="span-2">Notizen<textarea name="notes" rows="2">${esc(x.notes||'')}</textarea></label><label class="check-label"><input name="shared" type="checkbox" ${x.shared?'checked':''}> Gemeinsam absolviert</label></div>`);f.onsubmit=e=>{e.preventDefault();let v=Object.fromEntries(new FormData(f));Object.assign(x,{id:x.id||crypto.randomUUID(),...v,updatedAt:Date.now(),athlete:+v.athlete,rpe:+v.rpe||null,shared:f.elements.shared.checked,createdAt:x.createdAt||Date.now()});if(!existing)db.logs.push(x);f.closest('dialog').close();save()}}
function editLog(id){let x=db.logs.find(l=>l.id===id);if(x)logModal(x)}
function editTest(id){let x=db.tests.find(t=>t.id===id);if(!x)return;const f=modal(`Test bearbeiten · ${STATIONS[x.station].name}`,`<div class="form-grid"><label>Datum<input name="date" type="date" value="${x.date}"></label><label>Athletin<select name="athlete">${db.athletes.map((a,i)=>`<option value="${i}" ${x.athlete===i?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><label>Zeit (mm:ss)<input name="time" value="${formatTime(x.seconds)}"></label><label>Gewicht<input name="load" value="${esc(x.load)}"></label><label>Wiederholungen / Distanz<input name="work" value="${esc(x.work)}"></label><label>Pausen<input name="breaks" type="number" value="${x.breaks||0}"></label><label>RPE<input name="rpe" type="number" min="1" max="10" value="${x.rpe||''}"></label><label class="span-2">Technische Schwierigkeiten<input name="difficulty" value="${esc(x.difficulty||'')}"></label><label class="span-2">Bemerkungen<input name="notes" value="${esc(x.notes||'')}"></label><label class="check-label"><input name="valid" type="checkbox" ${x.valid?'checked':''}> Vergleichbarer Test</label></div>`);f.onsubmit=e=>{e.preventDefault();let v=new FormData(f);const seconds=parseTime(v.get('time'));if(!seconds)return alert('Bitte eine gültige Zeit eingeben.');Object.assign(x,{date:v.get('date'),updatedAt:Date.now(),athlete:+v.get('athlete'),seconds,load:v.get('load'),work:v.get('work'),breaks:+v.get('breaks'),rpe:+v.get('rpe'),difficulty:v.get('difficulty'),notes:v.get('notes'),valid:f.elements.valid.checked});f.closest('dialog').close();save()}}
function stationModal(i){const s=STATIONS[i],date=new Date().toISOString().slice(0,10);const f=modal(`Station ${String(i+1).padStart(2,'0')} · ${s.name}`,`<div class="form-grid"><label>Testdatum<input name="date" type="date" value="${date}" required></label><label>Stationszeit (mm:ss)<input name="time" placeholder="02:30" required></label><label>Gewicht<input name="load" value="${s.load}" required></label><label>Wiederholungen / Distanz<input name="work" value="${s.work}" required></label><label>Pausen<input name="breaks" type="number" min="0" value="0"></label><label>RPE 1–10<input name="rpe" type="number" min="1" max="10"></label><label class="span-2">Technische Schwierigkeiten<input name="difficulty" placeholder="z. B. Griff ermüdet"></label><label class="span-2">Bemerkungen<input name="notes" placeholder="Bedingungen, Seitenwechsel, Testnotiz"></label><label class="check-label"><input name="valid" type="checkbox" checked> Standardisierter, vergleichbarer Test</label></div>`);f.onsubmit=e=>{e.preventDefault();const x=new FormData(f),seconds=parseTime(x.get('time'));if(seconds<=0)return alert('Bitte eine gültige Zeit im Format mm:ss eingeben.');db.tests.push({id:crypto.randomUUID(),updatedAt:Date.now(),athlete:db.activeAthlete,station:i,date:x.get('date'),seconds,load:x.get('load'),work:x.get('work'),breaks:+x.get('breaks'),rpe:+x.get('rpe'),difficulty:x.get('difficulty'),notes:x.get('notes'),valid:x.get('valid')==='on',createdAt:Date.now()});f.closest('dialog').close();save()}}
function stopwatchModal(){const d=document.querySelector('#modal');d.innerHTML=`<div class="modal-card stopwatch-card"><button class="modal-close" data-close>×</button><span class="eyebrow">STATIONS-STOPPUHR</span><h2>Sauber messen.</h2><div id="stopwatch-clock" class="digital-clock">${formatTime(stopwatch.elapsed)}</div><label>Station<select id="sw-station">${STATIONS.map((s,i)=>`<option value="${i}">${String(i+1).padStart(2,'0')} · ${s.name}</option>`).join('')}</select></label><div class="timer-actions"><button class="primary-btn" id="sw-start">${stopwatch.startedAt?'Pause':'Start'}</button><button class="outline-btn" id="sw-save">Zeit übernehmen</button><button class="outline-btn" id="sw-reset">Zurücksetzen</button></div><p>Die Stoppuhr nutzt Zeitstempel und läuft weiter, wenn der Bildschirm gesperrt oder die App im Hintergrund ist.</p></div>`;d.showModal();d.querySelector('[data-close]').onclick=()=>d.close();const clock=d.querySelector('#stopwatch-clock');const tick=()=>{if(stopwatch.startedAt)stopwatch.elapsed=Math.floor((Date.now()-stopwatch.startedAt)/1000);clock.textContent=formatTime(stopwatch.elapsed)};clearInterval(timer);timer=setInterval(tick,250);d.querySelector('#sw-start').onclick=e=>{if(stopwatch.startedAt){stopwatch.elapsed=Math.floor((Date.now()-stopwatch.startedAt)/1000);stopwatch.startedAt=null;e.target.textContent='Fortsetzen'}else{stopwatch.startedAt=Date.now()-stopwatch.elapsed*1000;e.target.textContent='Pause'}tick()};d.querySelector('#sw-reset').onclick=()=>{stopwatch={startedAt:null,elapsed:0};tick();d.querySelector('#sw-start').textContent='Start'};d.querySelector('#sw-save').onclick=()=>{const i=+d.querySelector('#sw-station').value;const t=modal(`Zeit speichern · ${STATIONS[i].name}`,`<label>Testdatum<input name="date" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>RPE<input name="rpe" type="number" min="1" max="10"></label><label>Bemerkungen<input name="notes"></label><p>Gemessene Zeit: <b>${formatTime(stopwatch.elapsed)}</b></p>`);t.onsubmit=e=>{e.preventDefault();let x=new FormData(t);db.tests.push({id:crypto.randomUUID(),updatedAt:Date.now(),athlete:db.activeAthlete,station:i,date:x.get('date'),seconds:stopwatch.elapsed,load:STATIONS[i].load,work:STATIONS[i].work,rpe:+x.get('rpe'),notes:x.get('notes'),breaks:0,valid:true,createdAt:Date.now()});d.close();t.closest('dialog').close();save()}}}
function athletesModal(){const f=modal('Athletinnen bearbeiten',`<div class="form-grid">${db.athletes.map((a,i)=>`<label>Name Athletin ${i+1}<input name="name${i}" value="${esc(a.name)}" required></label><label>Akzentfarbe<input name="color${i}" type="color" value="${a.color}"></label>`).join('')}<label>Teamname<input name="team" value="${esc(db.teamName)}"></label></div>`);f.onsubmit=e=>{e.preventDefault();let x=new FormData(f);db.athletes.forEach((a,i)=>{a.name=x.get('name'+i);a.color=x.get('color'+i)});db.teamName=x.get('team');db.athletes.forEach(a=>a.updatedAt=Date.now());f.closest('dialog').close();save()}}
function moveSession(key,current){const f=modal('Trainingseinheit verschieben',`<label>Neues Datum<input name="date" type="date" value="${current}" required></label><p>Die Einheit bleibt in ihrer Trainingswoche; nur der geplante Termin ändert sich.</p>`);f.onsubmit=e=>{e.preventDefault();db.moves[key]=f.elements.date.value;f.closest('dialog').close();save()}}
function toggleCustom(id){const x=db.customWorkouts.find(w=>w.id===id);if(!x)return;const existing=db.logs.findIndex(l=>l.customId===id&&l.athlete===db.activeAthlete);if(existing>=0)db.logs.splice(existing,1);else db.logs.push({id:crypto.randomUUID(),updatedAt:Date.now(),customId:id,week:selectedWeek,session:99,date:new Date().toISOString().slice(0,10),title:x.title,type:'Workout',athlete:db.activeAthlete,shared:true,duration:x.duration||'',rpe:+x.rpe||null,notes:'',createdAt:Date.now()});save()}
function customModal(){const f=modal('Eigene Trainingseinheit',`<div class="form-grid"><label>Tag<input name="day" value="Samstag"></label><label>Titel<input name="title" required></label><label>Ziel<input name="goal"></label><label>Dauer<input name="duration" value="45 min"></label><label class="span-2">Warm-up<input name="warm"></label><label class="span-2">Hauptteil / Übungen<input name="work" required></label><label>RPE<input name="rpe" value="6"></label><label>Pause<input name="rest"></label><label class="span-2">Technik & Skalierung<input name="tech"></label><label class="span-2">Cool-down<input name="cool"></label></div>`);f.onsubmit=e=>{e.preventDefault();const x=Object.fromEntries(new FormData(f));db.customWorkouts.push({...x,week:selectedWeek,id:crypto.randomUUID()});f.closest('dialog').close();save()}}
function splitsModal(){const f=modal('Manuelle Stationsaufteilung',STATIONS.map((s,i)=>`<label class="split-row"><span>${String(i+1).padStart(2,'0')} · ${s.name}</span><select name="s${i}">${db.athletes.map((a,j)=>`<option value="${j}" ${db.race.splits[i]===j?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label>`).join(''));f.onsubmit=e=>{e.preventDefault();let x=new FormData(f);db.race.splits=STATIONS.map((s,i)=>+x.get('s'+i));f.closest('dialog').close();save()}}
function strategyModal(){const f=modal('Gemeinsame Wettkampfstrategie',`<div class="form-grid"><label>Zielzeit (mm:ss)<input name="target" placeholder="erst mit Daten festlegen" value="${db.race.targetSeconds?formatTime(db.race.targetSeconds):''}"></label><label>Gemeinsames Lauftempo (min/km)<input name="pace" value="${esc(db.race.pacing)}"></label><label class="span-2">Aufteilung & Wechsel-Absprachen<textarea name="notes" rows="4">${esc(db.race.notes)}</textarea></label>${['Anmeldung','Anreise','Kleidung','Schuhe','Ausrüstung','Ernährung','Flüssigkeitszufuhr','Aufwärmen','Wettkampfvorbereitung'].map(x=>`<label class="check-label"><input name="c:${x}" type="checkbox" ${db.race.checklist[x]?'checked':''}> ${x}</label>`).join('')}</div><p class="unconfirmed">Zielzeit nur aus belastbaren Test- und Laufdaten setzen. Paarsplitting ist flexibel; finale Details im aktuellen Regelbuch prüfen.</p>`);f.onsubmit=e=>{e.preventDefault();let x=new FormData(f);db.race.targetSeconds=parseTime(x.get('target'));db.race.pacing=x.get('pace');db.race.notes=x.get('notes');Object.keys(db.race.checklist).forEach(k=>delete db.race.checklist[k]);['Anmeldung','Anreise','Kleidung','Schuhe','Ausrüstung','Ernährung','Flüssigkeitszufuhr','Aufwärmen','Wettkampfvorbereitung'].forEach(k=>db.race.checklist[k]=x.get('c:'+k)==='on');db.settingsUpdatedAt=Date.now();f.closest('dialog').close();save()}}
function settingsModal(){const f=modal('Team & Datensicherung',`<div class="settings-block"><b>${db.status==='online'?'Geräteübergreifender Sync aktiv':'Lokale Speicherung aktiv'}</b><p>${db.status==='online'?'Daten werden mit dem Supabase-Team synchronisiert.':'Für zwei Telefone brauchst du ein Supabase-Projekt. Nutze das SQL-Schema und folge der Einrichtung in README.'}</p><button type="button" class="outline-btn" data-action="auth">${db.auth?.email?'Konto: '+esc(db.auth.email):'Anmelden / Registrieren'}</button></div><div class="settings-block"><b>Supabase-Verbindung</b><label>Projekt-URL<input name="sb-url" placeholder="https://….supabase.co" value="${esc(db.supabase?.url||'')}"></label><label>Public anon / publishable key<input name="sb-key" placeholder="eyJ…" value="${esc(db.supabase?.key||'')}"></label><small>Nur öffentliche anon/publishable keys. Kein Service-Role-Key.</small></div><div class="settings-block"><b>Trainingsstruktur · ${esc(db.athletes[db.activeAthlete].name)}</b><label>Trainingshäufigkeit pro Woche<select name="frequency">${[2,3,4,5,6,7].map(n=>`<option value="${n}" ${+(db.athletes[db.activeAthlete].frequency||4)===n?'selected':''}>${n} Tage</option>`).join('')}</select></label><div class="schedule-days">${['Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag','Sonntag'].map(d=>`<label class="check-label"><input type="checkbox" name="day:${d}" ${(db.athletes[db.activeAthlete].trainingDays||['Montag','Mittwoch','Samstag','Sonntag']).includes(d)?'checked':''}> ${d}</label>`).join('')}</div><small>Das verschiebt keine einzelnen Plankarten automatisch. Nutze ↗ an der Einheit, um ihren Termin festzulegen.</small></div><div class="settings-block"><b>Gemeinsames Team</b><label>Teamname<input name="team" value="${esc(db.teamName)}"></label><div class="settings-actions"><button type="button" class="outline-btn" data-action="make-team">Team erstellen</button><button type="button" class="outline-btn" data-action="sync-now">Sync now</button><button type="button" class="outline-btn" data-action="join-team">Mit Einladungscode beitreten</button></div>${db.invite?`<label>Einladungscode<input readonly value="${esc(db.invite)}"></label>`:''}</div><div class="settings-actions"><button type="button" class="outline-btn" data-action="export">JSON sichern</button><button type="button" class="outline-btn" data-action="import">JSON importieren</button><button type="button" class="outline-btn" data-action="export-csv">CSV exportieren</button></div><div id="sync-error" class="unconfirmed"></div><p class="ios-tip">iPhone: In Safari auf „Teilen“ → „Zum Home-Bildschirm“ tippen.</p>`,'Schließen');f.querySelector('.modal-actions').innerHTML=`<button type="button" class="outline-btn" value="cancel">Schließen</button><button class="primary-btn">Verbindung speichern</button>`;f.onsubmit=e=>{e.preventDefault();db.supabase={url:f.elements['sb-url'].value.trim().replace(/\/$/,''),key:f.elements['sb-key'].value.trim()};db.teamName=f.elements.team.value.trim()||db.teamName;db.settingsUpdatedAt=Date.now();const athlete=db.athletes[db.activeAthlete];athlete.frequency=+f.elements.frequency.value;athlete.trainingDays=['Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag','Sonntag'].filter(d=>f.elements['day:'+d].checked);f.closest('dialog').close();save();if(db.supabase.url&&db.supabase.key)initSupabase()};f.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));f.querySelector('[data-action="export-csv"]').onclick=exportCSV}
function authModal(){if(!db.supabase?.url||!db.supabase?.key)return alert('Trage zuerst die Supabase-URL und den öffentlichen anon/publishable-Key ein und speichere.');const f=modal('Supabase-Konto',`<label>E-Mail<input name="email" type="email" required></label><label>Passwort<input name="password" type="password" minlength="8" required></label><p>Registrierung schickt je nach Supabase-Einstellung eine Bestätigungsmail.</p><div class="settings-actions"><button type="button" class="outline-btn" data-auth="signup">Konto erstellen</button><button type="button" class="outline-btn" data-auth="login">Anmelden</button></div>`,'Abbrechen');f.querySelector('.modal-actions').innerHTML=`<button type="button" class="outline-btn" value="cancel">Schließen</button>`;f.querySelectorAll('[data-auth]').forEach(b=>b.onclick=async()=>{let x=new FormData(f),client=await supabase();const {data,error}=await client.auth[b.dataset.auth==='signup'?'signUp':'signInWithPassword'](b.dataset.auth==='signup'?{email:x.get('email'),password:x.get('password')}:{email:x.get('email'),password:x.get('password')});if(error)return alert(error.message);db.auth={email:x.get('email'),userId:data.user?.id||data.session?.user?.id};db.status='pending';localStorage.setItem('ddrz-data',JSON.stringify(db));f.closest('dialog').close();render();await initSupabase()})}
async function supabase(){if(!window.ddSupabase){const mod=await import('https://esm.sh/@supabase/supabase-js@2');window.ddSupabase=mod.createClient(db.supabase.url,db.supabase.key)}return window.ddSupabase}
async function initSupabase(){try{if(!db.supabase?.url||!db.supabase?.key)return;let c=await supabase(),{data}=await c.auth.getSession();if(data.session){db.auth={email:data.session.user.email,userId:data.session.user.id};db.status='pending';await syncPull(true)}else{db.status='local';render()}}catch(e){db.status='pending';render();console.warn('Supabase:',e)}}
async function makeTeam(){try{const c=await supabase(),{data,error}=await c.rpc('create_team',{team_name:db.teamName});if(error)throw error;db.teamId=data.team_id;db.invite=data.invite_code;db.status='pending';localStorage.setItem('ddrz-data',JSON.stringify(db));alert(`Team erstellt. Einladungscode: ${data.invite_code}`);render();await syncPush()}catch(e){alert('Team konnte nicht erstellt werden: '+e.message)}}
async function joinTeam(){const code=prompt('Einladungscode des Teams eingeben');if(!code)return;try{const c=await supabase(),{data,error}=await c.rpc('join_team',{invite_code:code.trim()});if(error)throw error;db.teamId=data.team_id;db.invite=null;db.status='pending';localStorage.setItem('ddrz-data',JSON.stringify(db));alert('Team beigetreten. Gemeinsame Daten werden geladen.');await syncPull(true)}catch(e){alert('Beitritt fehlgeschlagen: '+e.message)}}
function records(){return [...db.athletes.map((p,i)=>({id:`athlete-${i}`,type:'athlete',payload:p})),...db.logs.map(x=>({id:x.id,type:'log',payload:x})),...db.tests.map(x=>({id:x.id,type:'test',payload:x})),...db.runs.map(x=>({id:x.id,type:'run',payload:x})),...db.simulations.map(x=>({id:x.id,type:'simulation',payload:x})),...db.customWorkouts.map(x=>({id:x.id,type:'workout',payload:x})),...db.deleted.map(x=>({id:`tombstone-${x.id}`,type:'tombstone',payload:x})),{id:'settings',type:'settings',payload:{teamName:db.teamName,race:db.race,split:db.race.splits,moves:db.moves,updatedAt:db.settingsUpdatedAt}}]}
async function syncPush(){return syncPull(false)}
async function syncPull(force=false){if(!navigator.onLine){db.status='pending';render();return}if(!db.supabase?.url||!db.auth?.userId||!db.teamId){db.status='local';render();if(force)alert('Melde dich an und erstelle ein Team oder tritt einem bei.');return}try{let c=await supabase();let {data,error}=await c.from('team_records').select('record_id,record_type,payload,updated_at').eq('team_id',db.teamId).order('updated_at');if(error)throw error;let map=new Map(data.map(r=>[r.record_id,r]));for(const r of data){let p=r.payload,remoteMs=+(p.updatedAt||new Date(r.updated_at).getTime());if(r.record_type==='tombstone'){const [kind,id]=p.target.split(':');const arr={log:db.logs,test:db.tests,run:db.runs,simulation:db.simulations,workout:db.customWorkouts}[kind];if(arr){const n=arr.findIndex(x=>x.id===id);if(n>=0)arr.splice(n,1)}merge(db.deleted,p);continue}const arr={log:db.logs,test:db.tests,run:db.runs,simulation:db.simulations,workout:db.customWorkouts}[r.record_type];if(arr){const local=arr.find(x=>x.id===p.id);if(!local||+(local.updatedAt||0)<=remoteMs)merge(arr,p);continue}if(r.record_type==='athlete'){const i=+r.record_id.slice(-1);if(+(db.athletes[i]?.updatedAt||0)<=remoteMs)db.athletes[i]=p}if(r.record_id==='settings'&&+(db.settingsUpdatedAt||0)<=remoteMs){db.teamName=p.teamName||db.teamName;db.race={...db.race,...p.race};db.race.splits=p.split||db.race.splits;db.moves=p.moves||db.moves;db.settingsUpdatedAt=p.updatedAt||remoteMs}}for(const local of records()){const remote=map.get(local.id),localMs=+(local.payload?.updatedAt||0),remoteMs=+(remote?.payload?.updatedAt||new Date(remote?.updated_at||0).getTime());if(!remote||localMs>remoteMs){if(!local.payload.updatedAt)local.payload.updatedAt=Date.now();let {error:e}=await c.from('team_records').upsert({team_id:db.teamId,record_id:local.id,record_type:local.type,payload:local.payload,owner_id:db.auth.userId,updated_at:new Date(local.payload.updatedAt).toISOString()},{onConflict:'team_id,record_id'});if(e)throw e}}db.status='online';localStorage.setItem('ddrz-data',JSON.stringify(db));render()}catch(e){db.status='pending';render();if(force)alert('Synchronisierung nicht möglich: '+e.message)}}
function merge(arr,item){const i=arr.findIndex(x=>x.id===item.id);if(i<0)arr.push(item);else arr[i]={...arr[i],...item}}
async function signOut(){if(confirm('Vom Supabase-Konto abmelden?')){let c=await supabase();await c.auth.signOut();db.auth=null;db.teamId=null;db.status='local';save()}}
function addLog(f){const x=Object.fromEntries(f);db.logs.push({id:crypto.randomUUID(),updatedAt:Date.now(),date:x.date,title:x.title||'Training',type:'Workout',athlete:db.activeAthlete,shared:x.shared==='on',duration:x.duration||'',rpe:+x.rpe||null,notes:x.notes||'',week:selectedWeek,createdAt:Date.now()});save()}
function toggle(key){const [w,i]=key.split(':').map(Number);const old=db.logs.findIndex(l=>l.week===w&&l.session===i&&l.athlete===db.activeAthlete);if(old>=0)db.logs.splice(old,1);else{const s=trainingWeek(w)[i];db.logs.push({id:crypto.randomUUID(),updatedAt:Date.now(),week:w,session:i,date:new Date().toISOString().slice(0,10),title:s.title,type:s.kind,athlete:db.activeAthlete,shared:true,duration:s.duration,rpe:+(s.rpe.match(/\d+/)||[])[0]||null,notes:'',createdAt:Date.now()})}save()}
function addRun(f){const x=Object.fromEntries(f),seconds=parseTime(x.time);if(!seconds||+x.distance<=0)return alert('Distanz und Zeit eingeben.');db.runs.push({id:crypto.randomUUID(),updatedAt:Date.now(),athlete:db.activeAthlete,date:x.date,distance:+x.distance,seconds,hr:+x.hr||null,rpe:+x.rpe||null,notes:x.notes,shared:x.shared==='on'});save()}
function exportData(){const blob=new Blob([JSON.stringify({...db,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});download(blob,'deadly-dozen-backup.json')}
function exportCSV(){const rows=[['Datum','Athletin','Typ','Einheit','Zeit Sekunden','Distanz km','RPE','Notiz'],...db.logs.map(x=>[x.date,db.athletes[x.athlete]?.name,'Workout',x.title,'','',x.rpe,x.notes]),...db.runs.map(x=>[x.date,db.athletes[x.athlete]?.name,'Run','Lauf',x.seconds,x.distance,x.rpe,x.notes]),...db.tests.map(x=>[x.date,db.athletes[x.athlete]?.name,'Station',STATIONS[x.station]?.name,x.seconds,'',x.rpe,x.notes])];const csv=rows.map(r=>r.map(c=>`"${String(c??'').replaceAll('"','""')}"`).join(';')).join('\r\n');download(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),'deadly-dozen-export.csv')}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function importData(){const i=document.createElement('input');i.type='file';i.accept='application/json';i.onchange=async()=>{try{const x=JSON.parse(await i.files[0].text());if(!x.version)throw new Error('Ungültiges Backup');for(const k of ['logs','tests','runs','simulations','customWorkouts','deleted'])for(const v of x[k]||[])merge(db[k],v);db.athletes=x.athletes||db.athletes;db.race={...db.race,...x.race};save();alert('Backup zusammengeführt. Bestehende Einträge wurden anhand ihrer ID abgeglichen.')}catch(e){alert('Import fehlgeschlagen: '+e.message)}};i.click()}
function libraryView(){const d=document.querySelector('#modal');d.innerHTML=`<div class="modal-card library-modal"><button class="modal-close" data-close>×</button><span class="eyebrow">ÜBUNGSKOMPASS</span><h2>12 Wettkampfstationen</h2><div class="library-scroll">${STATIONS.map((s,i)=>`<article class="library-item"><div class="station-no">${String(i+1).padStart(2,'0')}</div><div><h3>${s.name}</h3><p><b>${s.work} · ${s.load}</b></p><small>${s.muscles}</small><p>${s.tip}</p><details><summary>Fehler, Vorbereitung & Standards</summary><p><b>Typische Fehler:</b> ${s.errors}</p><p><b>Vorübungen:</b> ${s.prep}</p><p><b>Offizieller Bewegungsstandard:</b> vor Wettkampf im aktuellen Regelbuch bestätigen; diese App behauptet keine vollständige Judge-Kriterienliste.</p><p><b>Eigene Bestzeit:</b> ${db.athletes.map((a,j)=>`${esc(a.name)} ${bestTime(i,j)}`).join(' · ')}</p></details></div></article>`).join('')}</div></div>`;d.showModal();d.querySelector('[data-close]').onclick=()=>d.close()}
function raceMode(){let leg=0,mode='ready',start=0,carry=0,parts=[],lastMark=0,raf=0,wake=null;const d=document.querySelector('#modal');const snapshot=()=>carry+(mode==='running'?Date.now()-start:0);const draw=()=>{let elapsed=snapshot(),station=Math.floor(leg/2),isRun=leg%2===0,done=mode==='done';d.innerHTML=`<div class="race-screen"><div class="race-top"><span>DEADLY DOZEN <i>RACE MODE</i></span><button class="modal-close" data-close>×</button></div><div class="race-status">${mode==='ready'?'BEREIT':mode==='running'?'LÄUFT':mode==='paused'?'PAUSIERT':'ABGESCHLOSSEN'}</div><div class="race-clock">${formatClockMs(elapsed)}</div><div class="race-progress"><i style="width:${Math.min(100,leg/24*100)}%"></i></div><div class="race-current"><span>${done?'FINISH':`ABSCHNITT ${String(Math.min(leg+1,24)).padStart(2,'0')} / 24 · ${isRun?'LAUF':'STATION'}`}</span><h2>${done?'Race complete':isRun?'200 m Lauf':STATIONS[station]?.name}</h2><b>${done?`Gesamtzeit ${formatTime(Math.floor(elapsed/1000))}`:isRun?'12 × 200 m · gemeinsam':`${STATIONS[station]?.load} · ${STATIONS[station]?.work}`}</b><small>${!isRun?`Zuständig: ${db.race.splits[station]!=null?db.athletes[db.race.splits[station]].name:'freie Aufteilung'}`:done?'12 Läufe · 12 Stationen':''}</small></div><div class="race-next">${done?'ZEITEN · '+parts.filter(p=>p.type==='run').length+' Läufe · '+parts.filter(p=>p.type==='station').length+' Stationen':isRun?`NÄCHSTE · ${STATIONS[station]?.name}`:station<11?`NÄCHSTER LAUF · ${String(station+2).padStart(2,'0')} / 12`:'LETZTE STATION'}</div><div class="race-buttons"><button id="race-primary">${mode==='running'?'PAUSE':mode==='ready'?'START':mode==='paused'?'FORTSETZEN':'NEUES RACE'}</button><button id="race-split">${done||leg>=24?'ERGEBNIS SPEICHERN':isRun?'LAUF ABSCHLIESSEN':'STATION ABSCHLIESSEN'}</button></div><small class="race-foot">Laufabschnitte und Stationen werden getrennt mit Zeitstempeln erfasst.</small></div>`;d.querySelector('[data-close]').onclick=()=>{if(mode==='running')pause();d.close()};d.querySelector('#race-primary').onclick=async()=>{if(mode==='done'){leg=0;mode='ready';carry=0;parts=[];lastMark=0;draw();return}if(mode==='running'){pause();return}mode='running';start=Date.now();try{wake=await navigator.wakeLock?.request('screen')}catch{}tick()};d.querySelector('#race-split').onclick=()=>{if(mode==='done'||leg>=24){finish();return}const elapsed=snapshot(),seconds=Math.max(0,Math.round((elapsed-lastMark)/1000));parts.push({leg,type:leg%2===0?'run':'station',station:Math.floor(leg/2),seconds});lastMark=elapsed;leg++;if(leg>=24){carry=elapsed;mode='paused';cancelAnimationFrame(raf)}draw()}};const tick=()=>{if(mode!=='running')return;const clock=d.querySelector('.race-clock');if(clock)clock.textContent=formatClockMs(snapshot());raf=requestAnimationFrame(tick)};function pause(){carry+=Date.now()-start;mode='paused';cancelAnimationFrame(raf);wake?.release();draw()}function finish(){const ms=snapshot(),seconds=Math.floor(ms/1000),run=parts.filter(p=>p.type==='run'),work=parts.filter(p=>p.type==='station'),fastest=work.length?Math.min(...work.map(x=>x.seconds)):null,slowest=work.length?Math.max(...work.map(x=>x.seconds)):null;db.simulations.push({id:crypto.randomUUID(),date:new Date().toISOString(),seconds,splits:parts,runSeconds:run.reduce((s,x)=>s+x.seconds,0),stationSeconds:work.reduce((s,x)=>s+x.seconds,0),fastest,slowest,athletes:db.athletes.map(a=>a.name)});mode='done';carry=seconds*1000;save();draw()}draw();d.showModal();d.addEventListener('close',()=>{cancelAnimationFrame(raf);wake?.release()},{once:true})}
function formatClockMs(ms){let s=Math.floor(ms/1000);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}.${String(Math.floor(ms%1000/100))}`}
document.addEventListener('input',e=>{if(e.target.id==='pace-input'){const p=+e.target.value*60,per=p*.2;document.querySelector('#pace-200').textContent=formatTime(per);document.querySelector('#pace-total').textContent=formatTime(p*2.4);document.querySelector('#pace-delta').textContent=formatTime((p+30)*2.4)}});
window.addEventListener('online',()=>{if(db.status==='pending')syncPull()});window.addEventListener('offline',()=>{db.status='pending';render()});
if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(console.warn);
render();if(db.supabase?.url&&db.supabase?.key)initSupabase();
